function frameHelmSensorDistance(
  sourceToken,
  targetToken
) {
  const source =
    sourceToken?.center;

  const target =
    targetToken?.center;

  if (
    !source ||
    !target
  ) {
    return Infinity;
  }

  try {
    const measured =
      canvas?.grid?.measurePath?.(
        [
          source,
          target
        ],
        {
          cost: true
        }
      );

    const sceneDistance =
      Number(
        canvas?.scene?.grid?.distance ??
        canvas?.dimensions?.distance ??
        1
      );

    const measuredDistance =
      Number(
        measured?.cost ??
        measured?.distance
      );

    if (
      Number.isFinite(
        measuredDistance
      )
    ) {
      return (
        Number.isFinite(
          sceneDistance
        ) &&
        sceneDistance > 0
      )
        ? measuredDistance /
          sceneDistance
        : measuredDistance;
    }
  } catch (error) {
    console.warn(
      `${MODULE_TITLE} | Sensor range measurement fell back to geometry.`,
      error
    );
  }

  const gridSize =
    Number(
      canvas?.dimensions?.size ??
      100
    );

  if (
    !Number.isFinite(gridSize) ||
    gridSize <= 0
  ) {
    return Infinity;
  }

  return Math.hypot(
    target.x - source.x,
    target.y - source.y
  ) / gridSize;
}

