function frameHelmSensorDistance(
  sourceToken,
  targetToken
) {
  const source =
    sourceToken?.center;

  const target =
    targetToken?.center;

  if (
    !source ||
    !target
  ) {
    return Infinity;
  }

  try {
    const measured =
      canvas?.grid?.measurePath?.(
        [
          source,
          target
        ],
        {
          cost: true
        }
      );

    /**
     * Foundry path cost is already expressed as grid traversal
     * cost/spaces. Do not divide it by the scene distance again.
     * Doing so previously shrank contact distances and allowed
     * enemies far outside a mech's Sensors to qualify.
     */
    const measuredCost =
      Number(
        measured?.cost
      );

    if (
      Number.isFinite(
        measuredCost
      )
    ) {
      return measuredCost;
    }

    /**
     * Some Foundry measurement paths expose physical scene
     * distance instead of traversal cost. Normalize that value
     * exactly once into Lancer grid spaces.
     */
    const measuredDistance =
      Number(
        measured?.distance
      );

    const sceneDistance =
      Number(
        canvas?.scene?.grid?.distance ??
        canvas?.dimensions?.distance ??
        1
      );

    if (
      Number.isFinite(
        measuredDistance
      )
    ) {
      return (
        Number.isFinite(
          sceneDistance
        ) &&
        sceneDistance > 0
      )
        ? measuredDistance /
          sceneDistance
        : measuredDistance;
    }
  } catch (error) {
    console.warn(
      `${MODULE_TITLE} | Sensor range measurement fell back to geometry.`,
      error
    );
  }

  const gridSize =
    Number(
      canvas?.dimensions?.size ??
      100
    );

  if (
    !Number.isFinite(gridSize) ||
    gridSize <= 0
  ) {
    return Infinity;
  }

  return Math.hypot(
    target.x - source.x,
    target.y - source.y
  ) / gridSize;
}

