function getFrameHelmSensorVisualConfiguration() {
  return {
    contactColor:
      frameHelmCssColorToNumber(
        frameHelmSensorCssValue(
          "--fh-sensor-contact-color",
          "#ff3030"
        ),
        0xff3030
      ),

    reticleStrokeWidth:
      frameHelmSensorCssNumber(
        "--fh-sensor-reticle-stroke-width",
        1.5
      ),

    reticleAlpha:
      frameHelmSensorCssNumber(
        "--fh-sensor-reticle-alpha",
        0.9
      ),

    reticleClearance:
      frameHelmSensorCssNumber(
