      frameHelmSensorCssNumber(
        "--fh-sensor-reticle-bracket-scale",
        0.28
      ),

    layerZIndex:
      frameHelmSensorCssNumber(
        "--fh-sensor-layer-z-index",
        100000
      )
  };
}

