function createFrameHelmSensorCircle(
  radius,
  visual
) {
  const graphics =
    new PIXI.Graphics();

  if (
    typeof graphics.circle === "function" &&
    typeof graphics.stroke === "function"
  ) {
    graphics
      .circle(
        0,
        0,
        radius
      )
      .stroke({
        color:
          visual.contactColor,

        width:
          visual.circleStrokeWidth,

        alpha:
          visual.circleAlpha
      });
  } else {
    graphics.lineStyle(
      visual.circleStrokeWidth,
      visual.contactColor,
      visual.circleAlpha
    );

    graphics.drawCircle(
      0,
      0,
      radius
    );
  }

  return graphics;
}


function createFrameHelmSensorLabel(
  name,
  visual
) {
  const style = {
    fontFamily:
      visual.fontFamily,

    fontSize:
      visual.labelFontSize,

    fontWeight:
      "bold",

    fill:
      visual.labelColor,

    stroke: {
      color:
        visual.labelStrokeColor,

      width:
        visual.labelStrokeWidth
    },

    align:
      "center"
  };

  let label;

  try {
    label =
      new PIXI.Text({
        text:
          name,

        style
      });
  } catch (_error) {
    const strokeHex =
      `#${visual.labelStrokeColor
        .toString(16)
        .padStart(6, "0")}`;

    label =
      new PIXI.Text(
        name,

        new PIXI.TextStyle({
          fontFamily:
            style.fontFamily,

          fontSize:
            style.fontSize,

          fontWeight:
            style.fontWeight,

          fill:
            style.fill,

          stroke:
            strokeHex,

          strokeThickness:
            visual.labelStrokeWidth,

          align:
            style.align
        })
      );
  }

  label.anchor?.set?.(
    0.5,
    1
  );

  return label;
}


/* ============================================================
   Sensor contact composition
   ============================================================ */

function createFrameHelmSensorContact(
  contact,
  visual
) {
  const container =
    new PIXI.Container();

  container.position.set(
    contact.x,
    contact.y
  );

  const radius =
    Math.max(
      visual.radiusMinimum,

      Math.min(
        Number(contact.width) || 30,
        Number(contact.height) || 30
      ) * visual.radiusScale
    );

  const circle =
    createFrameHelmSensorCircle(
      radius,
      visual
    );

  const label =
    createFrameHelmSensorLabel(
      contact.name ??
      "CONTACT",

      visual
    );

  label.position.set(
    0,
    -radius -
      visual.labelOffset
  );

  container.addChild(
    circle
  );

  container.addChild(
    label
  );

  return container;
}

