function createFrameHelmSensorReticle(
  contact,
  visual
) {
  const graphics =
    new PIXI.Graphics();

  const tokenWidth =
    Math.max(
      1,
      Number(contact.width) ||
        30
    );

  const tokenHeight =
    Math.max(
      1,
      Number(contact.height) ||
        30
    );

  const halfWidth =
    tokenWidth / 2 +
    visual.reticleClearance;

  const halfHeight =
    tokenHeight / 2 +
    visual.reticleClearance;

  const bracketLength =
    Math.min(
      halfWidth,
      halfHeight,
      Math.max(
        visual.reticleBracketMinimum,
        Math.min(
          halfWidth,
          halfHeight
        ) * visual.reticleBracketScale
      )
    );

  const drawBracketGeometry =
    () => {
      graphics
        .moveTo(
          -halfWidth + bracketLength,
          -halfHeight
        )
        .lineTo(
          -halfWidth,
          -halfHeight
        )
        .lineTo(
          -halfWidth,
          -halfHeight + bracketLength
        );

      graphics
        .moveTo(
          halfWidth - bracketLength,
          -halfHeight
        )
        .lineTo(
          halfWidth,
          -halfHeight
        )
        .lineTo(
          halfWidth,
          -halfHeight + bracketLength
        );

      graphics
        .moveTo(
          -halfWidth,
          halfHeight - bracketLength
        )
        .lineTo(
          -halfWidth,
          halfHeight
        )
        .lineTo(
          -halfWidth + bracketLength,
          halfHeight
        );

      graphics
        .moveTo(
          halfWidth - bracketLength,
          halfHeight
        )
        .lineTo(
          halfWidth,
          halfHeight
        )
        .lineTo(
          halfWidth,
          halfHeight - bracketLength
        );
    };

  if (
    typeof graphics.stroke ===
      "function"
  ) {
    drawBracketGeometry();

    graphics.stroke({
      color:
        visual.contactColor,

      width:
        visual.reticleStrokeWidth,

      alpha:
        visual.reticleAlpha
    });
  } else {
    graphics.lineStyle(
      visual.reticleStrokeWidth,
      visual.contactColor,
      visual.reticleAlpha
    );

    drawBracketGeometry();
  }

  return graphics;
}


/* ============================================================
   Sensor contact composition
   ============================================================ */

function createFrameHelmSensorContact(
  contact,
  visual
) {
  const container =
    new PIXI.Container();

  container.position.set(
    contact.x,
    contact.y
  );

  container.addChild(
    createFrameHelmSensorReticle(
      contact,
      visual
    )
  );

  return container;
}
